tool_calls:
mkdir -p /scripts && cat > /scripts/report.sh <<'EOF'
#!/usr/bin/env bash
# Usage: report.sh [-f csv|json] [-o file] [-v] [-h]

INPUT=/data/input.csv
format=csv
outfile=
verbose=0

usage() {
  cat <<USAGE
Usage: $0 [-f <format>] [-o <file>] [-v] [-h]
  -f <format>  Output format: csv or json (default: csv)
  -o <file>    Output file (default: stdout)
  -v           Verbose mode
  -h           Print this usage and exit
USAGE
}

while getopts ":f:o:vh" opt; do
  case $opt in
    f) format=$OPTARG ;;
    o) outfile=$OPTARG ;;
    v) verbose=1 ;;
    h) usage; exit 0 ;;
    :) echo "Error: option -$OPTARG requires an argument" >&2; usage >&2; exit 2 ;;
    \?) echo "Error: invalid option -$OPTARG" >&2; usage >&2; exit 2 ;;
  esac
done
shift $((OPTIND - 1))

case $format in
  csv|json) ;;
  *) echo "Error: invalid format '$format' (use csv or json)" >&2; exit 2 ;;
esac

if [[ ! -r $INPUT ]]; then
  echo "Error: cannot read $INPUT" >&2
  exit 1
fi

# Number of data rows (excluding header)
rows=$(awk 'NR>1 && NF' "$INPUT" | wc -l | tr -d ' ')

[[ $verbose -eq 1 ]] && echo "Verbose: processing $rows rows"

emit() {
  if [[ $format == csv ]]; then
    cat "$INPUT"
  else
    awk -F',' '
      function esc(s) { gsub(/\\/, "\\\\", s); gsub(/"/, "\\\"", s); return s }
      function val(s) {
        if (s ~ /^-?[0-9]+(\.[0-9]+)?$/) return s
        return "\"" esc(s) "\""
      }
      { sub(/\r$/, "") }
      NR==1 { for (i=1;i<=NF;i++) h[i]=$i; n=NF; next }
      NF==0 { next }
      {
        line = (cnt++ ? ",\n" : "") "  {"
        for (i=1;i<=n;i++) line = line (i>1 ? ", " : "") "\"" esc(h[i]) "\": " val($i)
        printf "%s}", line
      }
      BEGIN { print "[" }
      END { if (cnt) print ""; print "]" }
    ' "$INPUT"
  fi
}

if [[ -n $outfile ]]; then
  emit > "$outfile"
else
  emit
fi
EOF
chmod +x /scripts/report.sh; bash /scripts/report.sh -f json -v; echo ---; bash /scripts/report.sh | head -2; bash /scripts/report.sh -h

